export function professionalFigureExample(category,scene){
 const brief=scenes.get(category+':'+scene);
 if(!brief)throw Error('Missing complete drawing example: '+category+':'+scene);
 return example('绘制'+scene+'科研图。'+brief+'使用简洁白色背景，确保短标注清楚。');
}
